import java.util.*;

class Solution {
  public long interchangeableRectangles(int[][] rectangles) {
    Map<Long, Long> m = new HashMap<>();
    long ans = 0;
    for (int[] r : rectangles) {
      int g = gcd(r[0], r[1]);
      long k = ((long) (r[0] / g) << 32) | (r[1] / g & 0xffffffffL);
      long c = m.getOrDefault(k, 0L);
      ans += c;
      m.put(k, c + 1);
    }
    return ans;
  }

  private int gcd(int a, int b) {
    while (b != 0) {
      int t = a % b;
      a = b;
      b = t;
    }
    return a;
  }
}
